const offer=shell(`<small>DEINE EINBLICKE</small><h2>Muster, die du bemerkst.</h2><p class="wf-muted">Ein privater Blick auf deine aufgezeichneten Momente.</p><div style="display:flex;gap:6px;white-space:nowrap"><span class="wf-pill accent">Letzte Woche</span><span class="wf-pill">4 Wochen</span><span class="wf-pill">Gesamt</span></div><div class="wf-card"><div style="display:flex;gap:12px"><strong>Leitsatz</strong><span>Muster</span></div><small>LEITSATZ DER LETZTEN WOCHE</small><h3>„Ich darf mir Zeit nehmen.“</h3><p>4 Mal gewählt</p><button>Passende Momente ansehen</button></div><div class="wf-card"><span data-icon="bell"></span><h3>Neue Einblicke mitbekommen</h3><p>Wir benachrichtigen dich, wenn ein neuer Leitsatz oder ein neues Muster sichtbar wird.</p><button class="primary" data-goto="enabled">Benachrichtigungen aktivieren</button><button data-goto="dismissed">Jetzt nicht</button></div>`);
const enabled=shell(`<small>DEINE EINBLICKE</small><h2>Muster, die du bemerkst.</h2><div style="display:flex;gap:6px"><span class="wf-pill accent">Letzte Woche</span><span class="wf-pill">4 Wochen</span><span class="wf-pill">Gesamt</span></div><div class="wf-card"><strong>Muster</strong><h3>Freude taucht wiederholt in deinen Momenten auf.</h3><p>Beispiel mit synthetischen Daten</p><button>Passende Momente ansehen</button></div><p><span data-icon="check"></span> Benachrichtigungen sind aktiviert.</p><button data-goto="settings">In Einstellungen verwalten</button><h3>Emotionale Konstellation</h3><p class="wf-muted">Was du bemerkt hast.</p>`);
const settings=shell(`<small>EINSTELLUNGEN</small><h2>Dein Raum.</h2><small>PERSONALISIEREN</small><div class="wf-card"><h3>Erinnerung an deinen Gefühls-Check-in</h3><p>Tage und Zeiten wählen</p><hr/><h3>Leitsatz verwalten</h3><p>Jeden Leitsatz und seine Erinnerung verwalten</p><hr/><h3>Neue Einblicke</h3><label><input type="checkbox" checked/> Benachrichtigungen aktiviert</label><p>Für Leitsätze und Muster: letzte Woche, letzte 4 Wochen und insgesamt.</p><button data-goto="off">Deaktivieren</button></div><small>RECHTLICHES</small><p>Datenschutz · Nutzungsbedingungen</p>`);
const off=shell(`<small>EINSTELLUNGEN</small><h2>Dein Raum.</h2><div class="wf-card"><h3>Neue Einblicke</h3><p>Benachrichtigungen sind deaktiviert.</p><button class="primary" data-goto="settings">Aktivieren</button></div><p>Deine Einblicke bleiben in der App verfügbar.</p>`);
const dismissed=shell(`<small>DEINE EINBLICKE</small><h2>Muster, die du bemerkst.</h2><div class="wf-card"><strong>Leitsatz</strong><h3>„Ich darf mir Zeit nehmen.“</h3><button>Passende Momente ansehen</button></div><h3>Emotionale Konstellation</h3><p>Die Anfrage ist geschlossen.</p><button data-goto="off">Einstellungen öffnen</button>`);
const screens=[{id:"offer",name:"Einblick + opt-in",html:offer},{id:"enabled",name:"Activated",html:enabled},{id:"settings",name:"Settings",html:settings},{id:"off",name:"Disabled",html:off},{id:"dismissed",name:"Dismissed",html:dismissed}];
const rich=(id,markdown)=>({id,type:"rich-text",data:{markdown}});
const blocks=[
rich("outcome","### Outcome\nOffer notifications alongside an available Einblick and provide a matching settings control. One device-local opt-in covers Leitsatz and pattern insights for last week, last four weeks and all time. The wireframes are inferred from the existing Analytics and Settings components; German copy is proposed, and insight content is synthetic."),
rich("existing","### Reuse and scope\nReuse `InsightHero`, `primaryAnalyticsInsights`, `topLeitsaetzeForTimeframe`, `entriesForAnalyticsTimeframe`, and the existing root navigation actor. Keep current thresholds, tabs and time-frame definitions. Offer the opt-in below an available insight, once until dismissed or accepted; settings always allows reactivation. Request OS permission only after activation. Denial shows system-settings and permission-recheck actions, following the existing reminder flow. Insight notification preference remains separate from timed Leitsatz and Pulse reminders."),
rich("delivery","### What counts as new\nPersist a baseline at activation, so existing insights are not announced retroactively. Compare semantic identity per time frame: Leitsatz belief ID; pattern kind plus emotion/belief IDs. Counts, locale changes, tab changes and pattern cycling are not new insights. Persist deduplication across restarts. Combine multiple new insights from one evaluation into one generic notification; no journal or Leitsatz text on the lock screen. On notification tap, resolve the time frame and insight kind through the root actor; if its evidence is gone, show the normal current Einblicke screen.\n\nEvaluate only after check-ins and beliefs have hydrated successfully, after successful data changes, and on foreground/time-frame rollover. Imports and restores establish a fresh baseline without notification floods. Turning off prevents pending insight delivery and leaves other reminders active. Persistence or delivery failures stay retryable and cannot display a false enabled/sent status."),
rich("files","### Implementation sequence\n1. Reuse Analytics domain calculations; add a pure candidate and novelty model under `src/features/analytics/domain/` plus Effect schemas for preferences and delivery state. Define and test the consumer matrix before runtime integration.\n2. Reuse settings persistence conventions in `src/features/settings/domain/app-settings.ts`, `infrastructure/app-settings.repository.ts`, and `application/app-settings.store.ts`. Add backward-compatible disabled defaults, dismissed-offer state and baseline/deduplication persistence. Keep UI access through actors/stores.\n3. Reuse permission/channel patterns from `src/features/reminders/infrastructure/local-reminder.scheduler.ts`. Add an insight-specific notification adapter and integrate response dispatch with `reminder-notification.bridge.ts` so the application has one handler/listener contract. Extend `src/navigation/` and `src/constants.ts` for offer, permission, preference and notification-opening events.\n4. Reuse `SettingsActionRow` and the current Analytics hero shell in `src/features/settings/ui/settings-screen.tsx` and `src/features/analytics/ui/analytics-screen.tsx`; add the offer and settings controls with English/German fbtee copy. Add Harness coverage and navigation model paths."),
rich("validation","### Verification\nRun `pnpm verify` and `pnpm test:coverage`. Test every insight-kind × time-frame combination; empty/learning states; activation and dismissal; permission undetermined, granted and denied; native API failure; hydration pending, success and failure; persistence failure; imports; duplicates/restarts; changed evidence; ties; week rollover/timezone; disable during delivery; and cold/warm notification opening. Verify consumer behavior before initialization completes. Run persisted-data transactions against the native SurrealDB runtime with React Native Harness, not only mocked query strings. Use the committed synthetic archive fixture (133 moments, 15 beliefs), validate iOS and Android interactions, and inspect German layout. Before implementation, invoke implementation-delivery and read the exact Expo SDK 57 documentation."),
rich("questions-heading","### Open Questions"),
{id:"questions",type:"question-form",data:{questions:[{id:"delivery-scope",title:"Should notifications arrive while Youmotion is closed?",subtitle:"Current insights are computed locally; closed-app delivery requires a separate background scheduling design and platform verification.",mode:"single",options:[{id:"local",label:"First cut: when the app evaluates new insights",detail:"Recompute after data changes and on foreground. No promise of delivery while closed.",recommended:true},{id:"background",label:"Include closed-app delivery",detail:"Expand scope to background evaluation and scheduling; delivery reliability needs native device proof."}],required:true}],submitLabel:"Send review"}}
];
