const p=load("currentPlan");
const texts={
outcome:"### Outcome
Offer notifications alongside an available Einblick and provide a matching settings control. One device-local opt-in covers Leitsatz and pattern insights for last week, last four weeks and all time. Users choose immediate delivery or a preferred local time. Evaluate insights only while Youmotion is open; schedule already detected new insights with the OS so their notification can arrive while the app is closed. Wireframes are inferred from existing Analytics and Settings components; German copy is proposed and insight content is synthetic.",
identity:"### Detection and delivery
Persist a baseline at activation so existing insights are not announced retroactively. Compare semantic identity per time frame: Leitsatz belief ID; pattern kind plus emotion/belief IDs. Counts, locale changes, tab changes and pattern cycling are not new insights. Deduplication is lifetime per semantic identity and time frame until deliberate data reset. An insight disappearing and returning does not trigger another alert. Reactivation establishes a fresh baseline.

Evaluate only while the app is open, after check-ins and beliefs hydrate successfully, after successful data changes, and on foreground/time-frame rollover. No background computation is required. Imports and restores establish a fresh baseline without notification floods.

Delivery preference defaults to immediate, with an optional chosen local hour/minute. In scheduled mode, persist newly detected candidates and register one non-repeating local OS notification for the next occurrence of the chosen time (tomorrow if today's time has passed). Delivery can occur after the app closes because the notification was registered while it was open. If no new insight was detected, schedule nothing. Do not create daily recurring alerts or imply new insights are generated while closed.

Coalesce candidates detected before the pending delivery into one notification, retaining the stable request ID and target. Track baseline, pending/scheduled batch and announced identities separately; successful OS registration means scheduled, not confirmed delivered. Reconcile persisted requests with native pending notifications on next foreground, using an idempotent identifier to recover interrupted persistence/scheduling without duplicates. OS delivery is best effort; do not claim guaranteed receipt.

Changing the chosen time reschedules an outstanding batch; switching to immediate delivers the pending batch once. Disabling, restore or data reset cancels only insight-owned pending requests. On foreground, cancel invalid candidates and reconcile locale/timezone changes; while closed, the precomputed notification may remain until delivery. Use generic lock-screen text without journal or Leitsatz content.

For combined notification taps, choose the stable target by last week, last four weeks, all time; then Leitsatz before pattern; then semantic ID order. Keep IDs in the payload and resolve through the root actor after hydration. If evidence is gone, show normal current Einblicke. User-facing copy: 'Einblicke werden berechnet, wenn du Youmotion öffnest. Bereits erkannte neue Einblicke können wir dir zur gewählten Zeit melden – auch wenn die App geschlossen ist.'",
implementation:p.content.blocks.find(b=>b.id==="implementation").data.markdown.replace("baseline/deduplication persistence.","baseline/deduplication persistence, delivery mode, local hour/minute and pending scheduled batch.").replace("Add an insight-specific notification adapter","Add an insight-specific adapter for immediate delivery and idempotent one-shot OS scheduling, cancellation, time changes and foreground reconciliation").replace("add offer and settings controls","add offer, delivery mode/time picker and settings controls"),
verification:p.content.blocks.find(b=>b.id==="verification").data.markdown+"

Cover immediate vs chosen-time delivery; future time today vs passed time tomorrow; no candidate/no schedule; multiple detections before delivery; persistence/scheduling interruption; duplicate recovery; time change and disable with a pending batch; timezone/DST changes; foreground invalidation; and tap after delayed delivery. On iOS and Android, open with the synthetic fixture, detect a new insight, choose a nearby time, confirm native request registration, close the app and observe the one-shot notification without reopening. Confirm no recurring notification remains and unrelated reminder requests survive cancellation. No background insight computation.",
"questions-heading":"### Decisions confirmed"
};
const patches=Object.entries(texts).map(([blockId,markdown])=>({op:"update-rich-text",blockId,markdown}));
patches.push({op:"update-block",blockId:"questions",block:{id:"questions",type:"callout",data:{tone:"decision",body:"Evaluate insights only while the app is open. Offer a chosen notification time; an already detected insight may be delivered by a scheduled local notification while the app is closed. Background insight generation is deferred."}}});
store("revisionPatches",patches);
text(await tools.mcp__plan__update_visual_plan({planId:p.id,contentPatches:patches,note:"Apply user's delivery answer: foreground computation with optional scheduled closed-app notification delivery."}));

const patches=load("revisionPatches");patches[5]={op:"update-block",blockId:"questions",patch:{data:{questions:[{id:"delivery-scope",title:"Foreground evaluation with scheduled delivery",subtitle:"Confirmed: compute while open; deliver already detected insights at a chosen time even while closed.",mode:"single",options:[{id:"scheduled-local",label:"Foreground evaluation + optional chosen delivery time",detail:"Use one-shot local notifications; no background computation or daily alert without a new insight.",recommended:true}],required:false}],submitLabel:"Send additional feedback"}}};
const p=load("currentPlan");
const newOfferCopy="Neue Einblicke berechnen wir beim Öffnen. Du kannst sofort oder zur gewählten Zeit benachrichtigt werden – auch wenn die App dann geschlossen ist.";
const timing=`<p>Berechnung beim Öffnen; Zustellung auch bei geschlossener App.</p><div style="display:flex;gap:8px"><button data-goto="settings">Sofort</button><button class="primary" data-goto="scheduled">Zur Uhrzeit</button></div><label>Uhrzeit <input type="time" value="19:00"/></label>`;
for(const frame of p.content.canvas.frames){
const edits=[];
if(frame.id==="offer")edits.push({find:"Wir benachrichtigen dich, wenn ein neuer Leitsatz oder ein neues Muster sichtbar wird.",replace:newOfferCopy});
if(frame.id==="settings")edits.push({find:"<button data-goto=\"off\">Deaktivieren</button>",replace:timing+'<button data-goto="off">Deaktivieren</button>'});
if(edits.length)patches.push({op:"patch-wireframe-html",blockId:frame.id,edits});
}
for(const s of p.content.prototype.screens){
let html=s.html;
if(s.id==="offer")html=html.replace("Wir benachrichtigen dich, wenn ein neuer Leitsatz oder ein neues Muster sichtbar wird.",newOfferCopy);
if(s.id==="settings")html=html.replace('<button data-goto="off">Deaktivieren</button>',timing.replaceAll('data-goto="scheduled"','data-goto="settings"')+'<button data-goto="off">Deaktivieren</button>');
if(html!==s.html)patches.push({op:"update-prototype-screen",screenId:s.id,patch:{html}});
}
store("revisionPatches",patches);
text(await tools.mcp__plan__update_visual_plan({planId:p.id,contentPatches:patches,note:"Apply confirmed foreground evaluation and optional chosen-time OS delivery while closed; align document, canvas and prototype."}));

const p=load("currentPlan");let patches=load("revisionPatches");
patches=patches.map(x=>{
if(x.op!=="patch-wireframe-html")return x;
const frame=p.content.canvas.frames.find(f=>f.id===x.blockId);
