export async function reconcileInsightBatch(batch: InsightBatch | null, locale: AppLocale) {
  const requests = await Notifications.getAllScheduledNotificationsAsync();
  const own = requests.filter(({ content }) => content.data?.['owner'] === INSIGHT_NOTIFICATION_OWNER);
  const expected = batch ? Schema.encodeSync(Schema.parseJson(Schema.Struct({
