import type { InsightCandidate } from '../domain/insight-notification';
import { InsightNotificationCoordinator, systemInsightDependencies, watchInsightAppState, type InsightData, type InsightNotificationCommand } from './insight-notification-coordinator';
import { insightNotificationStore } from './insight-notification.store';

export interface InsightRuntimeBinding {
  data: () => InsightData;
  subscribe: (notify: () => void) => { unsubscribe: () => void };
  onStop: (stop: () => void) => void;
}
export interface InsightNotificationRuntime {
  start: (binding: InsightRuntimeBinding) => void;
  command: (event: InsightNotificationCommand) => void;
  reset: () => void;
}
export function createInsightNotificationRuntime(): InsightNotificationRuntime {
  const coordinator = new InsightNotificationCoordinator(insightNotificationStore, systemInsightDependencies);
  return {
    start(binding) {
      let previous: InsightData | undefined;
      const notify = () => {
        const data = binding.data();
        if (previous?.entries === data.entries && previous.statements === data.statements
