      <ActionButton disabled={!hydrated || busy} label={settings.enabled ? String(fbs('Deactivate notifications', 'Disable insight notifications')) : String(fbs('Activate notifications', 'Enable insight notifications'))} onPress={settings.enabled ? _disable : _enable} testID="insight-notification-toggle" />
      {blocked ? <>
        <ActionButton label={String(fbs('Open system settings', 'Open insight notification system settings'))} onPress={_settings} secondary testID="insight-notification-system-settings" />
        <ActionButton label={String(fbs('Check again', 'Recheck insight notification permission'))} onPress={_recheck} secondary testID="insight-notification-recheck" />
      </> : null}
      {offer ? <ActionButton disabled={busy} label={String(fbs('Not now', 'Dismiss insight notification offer'))} onPress={_dismiss} secondary testID="insight-notification-dismiss" /> : null}
    </View>
  );
}
